$f_configmap_notifier_yaml = @'
# Non-secret settings for ITInventory.ExpirationNotifier.
apiVersion: v1
kind: ConfigMap
metadata:
  name: itinventory-notifier-config
  labels:
    app: itinventory-notifier
data:
  ExpirationNotifier__UpcomingWindowDays: "90"
  ExpirationNotifier__RunAtHour: "8"
  ExpirationNotifier__RunAtMinute: "0"
  Smtp__Enabled: "true"
  Smtp__Host: "CHANGE_ME"
  Smtp__Port: "25"
  Smtp__EnableSsl: "false"
  Smtp__FromAddress: "itenvanter@ziraatbank.com.tr"
  Smtp__FromDisplayName: "IT Envanter Sistemi"
'@
Write-RepoFile -RelativePath 'openshift\configmap-notifier.yaml' -Content $f_configmap_notifier_yaml

$f_configmap_web_yaml = @'
# Non-secret settings for ITInventory.Web. Double underscores map to nested appsettings.json
# keys (Ldap__Domain -> "Ldap":{"Domain":...}) -- standard ASP.NET Core env var convention.
#
# TestLogin lets anyone log in with a single shared password without touching AD -- keep it
# disabled ("false") on anything reachable by real users. It exists for local/demo use only.
apiVersion: v1
kind: ConfigMap
metadata:
  name: itinventory-web-config
  labels:
    app: itinventory-web
data:
  ASPNETCORE_ENVIRONMENT: "Production"
  Ldap__Domain: "fintek.local"
  Ldap__Servers__0: "fintek.local"
  Ldap__Port: "636"
  Ldap__UseSsl: "true"
  TestLogin__Enabled: "false"
'@
Write-RepoFile -RelativePath 'openshift\configmap-web.yaml' -Content $f_configmap_web_yaml

$f_deployment_notifier_yaml = @'
# ITInventory.ExpirationNotifier is a long-running worker that schedules its own daily run
# internally (see Workers/ExpirationCheckWorker.cs) -- not a one-shot job, so this is a
# Deployment, not a CronJob. Keep replicas at 1: it's not built for leader election, so a
# second replica would send every expiration email twice.
apiVersion: apps/v1
kind: Deployment
metadata:
  name: itinventory-notifier
  labels:
    app: itinventory-notifier
spec:
  replicas: 1
  strategy:
    type: Recreate
  selector:
    matchLabels:
      app: itinventory-notifier
  template:
    metadata:
      labels:
        app: itinventory-notifier
    spec:
      containers:
        - name: itinventory-notifier
          # Replace with your pushed image, e.g. an ImageStream tag:
          # image-registry.openshift-image-registry.svc:5000/<namespace>/itinventory-notifier:latest
          image: CHANGE_ME/itinventory-notifier:latest
          envFrom:
            - configMapRef:
                name: itinventory-notifier-config
            - secretRef:
                name: itinventory-secrets
          volumeMounts:
            - name: logs
              mountPath: /app/logs
          resources:
            requests:
              cpu: 50m
              memory: 128Mi
            limits:
              cpu: 250m
              memory: 256Mi
          securityContext:
            allowPrivilegeEscalation: false
            runAsNonRoot: true
            capabilities:
              drop:
                - ALL
            seccompProfile:
              type: RuntimeDefault
      volumes:
        # Its daily text log file is a convenience copy of what already goes to stdout
        # (readable via `oc logs`) -- emptyDir is fine, nothing here needs to survive a
        # pod restart.
        - name: logs
          emptyDir: {}
'@
Write-RepoFile -RelativePath 'openshift\deployment-notifier.yaml' -Content $f_deployment_notifier_yaml

$f_deployment_web_yaml = @'
apiVersion: apps/v1
kind: Deployment
metadata:
  name: itinventory-web
  labels:
    app: itinventory-web
spec:
  replicas: 1
  selector:
    matchLabels:
      app: itinventory-web
  template:
    metadata:
      labels:
        app: itinventory-web
    spec:
      containers:
        - name: itinventory-web
          # Replace with your pushed image, e.g. an ImageStream tag:
          # image-registry.openshift-image-registry.svc:5000/<namespace>/itinventory-web:latest
          image: CHANGE_ME/itinventory-web:latest
          ports:
            - containerPort: 8080
          envFrom:
            - configMapRef:
                name: itinventory-web-config
            - secretRef:
                name: itinventory-secrets
          volumeMounts:
            - name: dataprotection-keys
              mountPath: /app/keys
          readinessProbe:
            httpGet:
              path: /healthz/ready
              port: 8080
            initialDelaySeconds: 10
            periodSeconds: 10
            timeoutSeconds: 5
            failureThreshold: 3
          livenessProbe:
            httpGet:
              path: /healthz/live
              port: 8080
            initialDelaySeconds: 15
            periodSeconds: 20
            timeoutSeconds: 5
            failureThreshold: 3
          resources:
            requests:
              cpu: 100m
              memory: 256Mi
            limits:
              cpu: 500m
              memory: 512Mi
          # No runAsUser/runAsGroup/fsGroup: OpenShift's restricted-v2 SCC assigns an
          # arbitrary UID (always group 0) at admission time and rejects a fixed one anyway.
          # The rest of this block is what restricted-v2 requires explicitly.
          securityContext:
            allowPrivilegeEscalation: false
            runAsNonRoot: true
            capabilities:
              drop:
                - ALL
            seccompProfile:
              type: RuntimeDefault
      volumes:
        - name: dataprotection-keys
          persistentVolumeClaim:
            claimName: itinventory-web-dataprotection-keys
'@
Write-RepoFile -RelativePath 'openshift\deployment-web.yaml' -Content $f_deployment_web_yaml

$f_imagestream_buildconfig_yaml = @'
# OPTIONAL: only needed if you want OpenShift itself to build the images from git (Docker
# build strategy) instead of pushing images built elsewhere (your own CI, `docker push`,
# etc.) into the same ImageStreams. If you already have a pipeline, skip this file --
# just push to whatever registry/tag deployment-web.yaml and deployment-notifier.yaml
# reference and skip this file entirely.
#
# CHANGE_ME: repo URL/branch below point at this project's GitHub remote; update the
# branch (and add a `contextDir`/`sourceSecret` if the repo is private) for your setup.
# Trigger a build after applying with:  oc start-build itinventory-web
apiVersion: image.openshift.io/v1
kind: ImageStream
metadata:
  name: itinventory-web
---
apiVersion: build.openshift.io/v1
kind: BuildConfig
metadata:
  name: itinventory-web
spec:
  source:
    type: Git
    git:
      uri: https://github.com/naklovas/Futbolquiz.git
      ref: CHANGE_ME
    contextDir: it-inventory
  strategy:
    type: Docker
    dockerStrategy:
      dockerfilePath: Dockerfile
  output:
    to:
      kind: ImageStreamTag
      name: itinventory-web:latest
  triggers:
    - type: ConfigChange
---
apiVersion: image.openshift.io/v1
kind: ImageStream
metadata:
  name: itinventory-notifier
---
apiVersion: build.openshift.io/v1
kind: BuildConfig
metadata:
  name: itinventory-notifier
spec:
  source:
    type: Git
    git:
      uri: https://github.com/naklovas/Futbolquiz.git
      ref: CHANGE_ME
    contextDir: it-inventory
  strategy:
    type: Docker
    dockerStrategy:
      dockerfilePath: src/ITInventory.ExpirationNotifier/Dockerfile
  output:
    to:
      kind: ImageStreamTag
      name: itinventory-notifier:latest
  triggers:
    - type: ConfigChange
'@
Write-RepoFile -RelativePath 'openshift\imagestream-buildconfig.yaml' -Content $f_imagestream_buildconfig_yaml

$f_pvc_dataprotection_keys_yaml = @'
# Small persistent volume for the Data Protection key ring (see Program.cs /
# DataProtection__KeysDirectory) so login cookies survive pod restarts/redeploys.
# ReadWriteOnce is enough at replicas: 1. If you ever scale itinventory-web beyond one
# replica, all replicas must share the SAME key ring or they won't be able to decrypt each
# other's auth cookies -- switch the deployment's replica count only after also switching
# this to a ReadWriteMany-capable storage class (or move keys to a different backing store).
apiVersion: v1
kind: PersistentVolumeClaim
metadata:
  name: itinventory-web-dataprotection-keys
  labels:
    app: itinventory-web
spec:
  accessModes:
    - ReadWriteOnce
  resources:
    requests:
      storage: 100Mi
'@
Write-RepoFile -RelativePath 'openshift\pvc-dataprotection-keys.yaml' -Content $f_pvc_dataprotection_keys_yaml

$f_route_web_yaml = @'
# Edge TLS termination: the router holds the certificate and speaks plain HTTP to the pod
# (matches ASPNETCORE_FORWARDEDHEADERS_ENABLED=true in the Dockerfile -- the app trusts the
# router's X-Forwarded-Proto header to know the original request was https).
# insecureEdgeTerminationPolicy: Redirect means the router itself bounces any plain http
# request to https before it ever reaches the pod, so app.UseHttpsRedirection() in
# Program.cs never actually has to fire for real traffic.
apiVersion: route.openshift.io/v1
kind: Route
metadata:
  name: itinventory-web
  labels:
    app: itinventory-web
spec:
  # CHANGE_ME: pick the hostname branches/users will actually use, e.g.
  # itinventory.CHANGE_ME.example.com. Omit `host` entirely to let OpenShift generate one
  # from the Route name + namespace + cluster's default subdomain.
  host: CHANGE_ME
  to:
    kind: Service
    name: itinventory-web
  port:
    targetPort: http
  tls:
    termination: edge
    insecureEdgeTerminationPolicy: Redirect
'@
Write-RepoFile -RelativePath 'openshift\route-web.yaml' -Content $f_route_web_yaml

$f_secret_example_yaml = @'
# TEMPLATE ONLY -- do not fill in real values here and commit this file.
#
# Create the real secret directly against the cluster instead, e.g.:
#
#   oc create secret generic itinventory-secrets \
#     --from-literal=ConnectionStrings__ITInventory='Server=sqlhost;Database=ITInventory;User Id=...;Password=...;TrustServerCertificate=True;' \
#     --from-literal=Smtp__Username='...' \
#     --from-literal=Smtp__Password='...'
#
# Shared by both Deployments (Web reads ConnectionStrings__ITInventory only; the Notifier
# reads ConnectionStrings__ITInventory + Smtp__Username/Smtp__Password). One Secret is fine
# since both live in the same namespace and need overlapping keys -- split it if your
# cluster's RBAC wants tighter separation between the two workloads.
apiVersion: v1
kind: Secret
metadata:
  name: itinventory-secrets
  labels:
    app: itinventory
type: Opaque
stringData:
  ConnectionStrings__ITInventory: "CHANGE_ME"
  Smtp__Username: "CHANGE_ME"
  Smtp__Password: "CHANGE_ME"
'@
Write-RepoFile -RelativePath 'openshift\secret.example.yaml' -Content $f_secret_example_yaml

$f_service_web_yaml = @'
apiVersion: v1
kind: Service
metadata:
  name: itinventory-web
  labels:
    app: itinventory-web
spec:
  selector:
    app: itinventory-web
  ports:
    - name: http
      port: 8080
      targetPort: 8080
'@
Write-RepoFile -RelativePath 'openshift\service-web.yaml' -Content $f_service_web_yaml

