$f_ServerConfiguration_cs = @'
using ITInventory.Data.Common;
using ITInventory.Data.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ITInventory.Data.Configurations;

public class ServerConfiguration : IEntityTypeConfiguration<Server>
{
    public void Configure(EntityTypeBuilder<Server> builder)
    {
        builder.ToTable("Servers", "dbo");

        builder.HasKey(x => x.Id);

        builder.Property(x => x.HostName).HasMaxLength(255).IsRequired();
        builder.Property(x => x.OperatingSystem).HasMaxLength(255);
        builder.Property(x => x.Brand).HasMaxLength(100);
        builder.Property(x => x.Model).HasMaxLength(150);
        builder.Property(x => x.SerialNo).HasMaxLength(150);
        builder.Property(x => x.VendorSupplier).HasMaxLength(150);
        builder.Property(x => x.Branch).HasMaxLength(150);
        builder.Property(x => x.Location).HasMaxLength(255);
        builder.Property(x => x.CreatedBy).HasMaxLength(100);
        builder.Property(x => x.UpdatedBy).HasMaxLength(100);
        builder.Property(x => x.ApplianceType).HasConversion<string>().HasMaxLength(20);
        builder.Property(x => x.LocationCategory)
            .HasConversion(
                v => v.ToString(),
                v => v == "EVM" ? LocationCategory.Turkiye : Enum.Parse<LocationCategory>(v))
            .HasMaxLength(20);
        builder.Property(x => x.SiteRole).HasConversion<string>().HasMaxLength(20);

        builder.HasOne(x => x.Country)
            .WithMany(c => c.Servers)
            .HasForeignKey(x => x.CountryId)
            .OnDelete(DeleteBehavior.Restrict);

        builder.HasOne(x => x.DeviceProfile)
            .WithMany()
            .HasForeignKey(x => x.DeviceProfileId)
            .OnDelete(DeleteBehavior.SetNull);

        builder.HasOne(x => x.HostPhysicalDevice)
            .WithMany()
            .HasForeignKey(x => x.HostPhysicalDeviceId)
            .OnDelete(DeleteBehavior.SetNull);

        builder.HasIndex(x => x.CountryId);
        builder.HasIndex(x => x.HostPhysicalDeviceId);
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Data\Configurations\ServerConfiguration.cs' -Content $f_ServerConfiguration_cs

$f_ServerEndpointConfiguration_cs = @'
using ITInventory.Data.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ITInventory.Data.Configurations;

public class ServerEndpointConfiguration : IEntityTypeConfiguration<ServerEndpoint>
{
    public void Configure(EntityTypeBuilder<ServerEndpoint> builder)
    {
        builder.ToTable("ServerEndpoints", "dbo");

        builder.HasKey(x => x.Id);

        builder.Property(x => x.IpAddress).HasMaxLength(50);
        builder.Property(x => x.CreatedBy).HasMaxLength(100);
        builder.Property(x => x.UpdatedBy).HasMaxLength(100);

        builder.HasOne(x => x.Server)
            .WithMany(s => s.Endpoints)
            .HasForeignKey(x => x.ServerId)
            .OnDelete(DeleteBehavior.Cascade);

        builder.HasOne(x => x.Application)
            .WithMany(a => a.ServerEndpoints)
            .HasForeignKey(x => x.ApplicationId)
            .OnDelete(DeleteBehavior.SetNull);

        builder.HasIndex(x => x.ServerId);
        builder.HasIndex(x => x.ApplicationId);
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Data\Configurations\ServerEndpointConfiguration.cs' -Content $f_ServerEndpointConfiguration_cs

$f_VropsDatacenterConfiguration_cs = @'
using ITInventory.Data.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ITInventory.Data.Configurations;

public class VropsDatacenterConfiguration : IEntityTypeConfiguration<VropsDatacenter>
{
    public void Configure(EntityTypeBuilder<VropsDatacenter> builder)
    {
        builder.ToTable("VropsDatacenters", "dbo");

        builder.HasKey(x => x.Id);
        builder.Property(x => x.DatacenterName).HasMaxLength(255).IsRequired();

        // Ayni datacenter iki ulkeye baglanamaz.
        builder.HasIndex(x => x.DatacenterName).IsUnique();

        builder.HasOne(x => x.Country)
            .WithMany()
            .HasForeignKey(x => x.CountryId)
            .OnDelete(DeleteBehavior.Cascade);
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Data\Configurations\VropsDatacenterConfiguration.cs' -Content $f_VropsDatacenterConfiguration_cs

