$f_YdUserConfiguration_cs = @'
using ITInventory.Data.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ITInventory.Data.Configurations;

public class YdUserConfiguration : IEntityTypeConfiguration<YdUser>
{
    public void Configure(EntityTypeBuilder<YdUser> builder)
    {
        builder.ToTable("YDUsers", "dbo", t => t.ExcludeFromMigrations());

        builder.HasKey(x => x.Id);
        builder.Property(x => x.Id).ValueGeneratedOnAdd();
        builder.Property(x => x.Username).HasMaxLength(100).IsRequired();
        builder.Property(x => x.FullName).HasMaxLength(100).IsRequired();
        builder.Property(x => x.Email).HasMaxLength(100);
        builder.Property(x => x.RepositoryName).HasMaxLength(255);
        builder.Property(x => x.ReceiveExpirationNotifications).HasDefaultValue(true);
        builder.HasIndex(x => x.Username).IsUnique();
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Data\Configurations\YdUserConfiguration.cs' -Content $f_YdUserConfiguration_cs

$f_YdUserRoleConfiguration_cs = @'
using ITInventory.Data.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ITInventory.Data.Configurations;

public class YdUserRoleConfiguration : IEntityTypeConfiguration<YdUserRole>
{
    public void Configure(EntityTypeBuilder<YdUserRole> builder)
    {
        builder.ToTable("YDUserRoles", "dbo", t => t.ExcludeFromMigrations());

        builder.HasKey(x => new { x.UserId, x.RoleId });

        builder.HasOne(x => x.User)
            .WithMany(u => u.UserRoles)
            .HasForeignKey(x => x.UserId);

        builder.HasOne(x => x.Role)
            .WithMany(r => r.UserRoles)
            .HasForeignKey(x => x.RoleId);
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Data\Configurations\YdUserRoleConfiguration.cs' -Content $f_YdUserRoleConfiguration_cs

