$f_FileLoggerProvider_cs = @'
using Microsoft.Extensions.Logging;

namespace ITInventory.ExpirationNotifier.Logging;

/// <summary>
/// Plain per-day text log under logs\ next to the executable -- a Windows Service has no
/// console to watch, so this is how a non-technical admin checks what the service did.
/// </summary>
public class FileLoggerProvider : ILoggerProvider
{
    private readonly string _logDirectory;
    private readonly object _writeLock = new();

    public FileLoggerProvider(string logDirectory)
    {
        _logDirectory = logDirectory;
        Directory.CreateDirectory(_logDirectory);
    }

    public ILogger CreateLogger(string categoryName) => new FileLogger(categoryName, _logDirectory, _writeLock);

    public void Dispose() { }

    private class FileLogger : ILogger
    {
        private readonly string _categoryName;
        private readonly string _logDirectory;
        private readonly object _writeLock;

        public FileLogger(string categoryName, string logDirectory, object writeLock)
        {
            _categoryName = categoryName;
            _logDirectory = logDirectory;
            _writeLock = writeLock;
        }

        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;

        public bool IsEnabled(LogLevel logLevel) => logLevel >= LogLevel.Information;

        public void Log<TState>(LogLevel logLevel, EventId eventId, TState state, Exception? exception, Func<TState, Exception?, string> formatter)
        {
            if (!IsEnabled(logLevel)) return;

            var line = $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} [{logLevel}] {_categoryName}: {formatter(state, exception)}";
            if (exception != null) line += Environment.NewLine + exception;

            var path = Path.Combine(_logDirectory, $"expiration-notifier-{DateTime.Now:yyyy-MM-dd}.log");
            lock (_writeLock)
            {
                File.AppendAllText(path, line + Environment.NewLine);
            }
        }
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.ExpirationNotifier\Logging\FileLoggerProvider.cs' -Content $f_FileLoggerProvider_cs

$f_ExpiringItemNotification_cs = @'
namespace ITInventory.ExpirationNotifier.Models;

public enum ExpirationType
{
    License,
    EndOfSupport,
    EndOfLife
}

public class ExpiringItemNotification
{
    public string Category { get; set; } = string.Empty;
    public string Label { get; set; } = string.Empty;
    public ExpirationType ExpirationType { get; set; }
    public string Name { get; set; } = string.Empty;
    public int CountryId { get; set; }
    public string CountryName { get; set; } = string.Empty;
    public DateTime ExpiresAt { get; set; }
}

public class NotificationRecipient
{
    public string FullName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

/// <summary>
/// One country's worth of expiring items plus who should be emailed about them:
/// that country's users (YDUsers.RepositoryName == Countries.Name, same match the
/// web app uses to scope a logged-in user to a country) union every admin.
/// </summary>
public class CountryNotificationGroup
{
    public int CountryId { get; set; }
    public string CountryName { get; set; } = string.Empty;
    public List<NotificationRecipient> Recipients { get; set; } = new();
    public List<ExpiringItemNotification> ExpiredItems { get; set; } = new();
    public List<ExpiringItemNotification> UpcomingItems { get; set; } = new();
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.ExpirationNotifier\Models\ExpiringItemNotification.cs' -Content $f_ExpiringItemNotification_cs

$f_Program_cs = @'
using ITInventory.Data;
using ITInventory.ExpirationNotifier.Logging;
using ITInventory.ExpirationNotifier.Services;
using ITInventory.ExpirationNotifier.Workers;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

var builder = Host.CreateApplicationBuilder(args);

// Lets the same .exe run as a normal console app (dotnet run, for testing) or as an
// installed Windows Service (sc.exe create ... binPath= "...exe") -- it detects which.
builder.Services.AddWindowsService(options =>
{
    options.ServiceName = "ITInventory Expiration Notifier";
});

var connectionString = builder.Configuration.GetConnectionString("ITInventory");
builder.Services.AddDbContext<ITInventoryDbContext>(options => options.UseSqlServer(connectionString));

// Relay not configured yet (or Smtp:Enabled is false) -> keep logging what would be sent
// instead of actually sending. Once the relay details are filled in and Enabled is set to
// true, this switches to real email with no other code changes needed.
var smtpEnabled = builder.Configuration.GetValue<bool?>("Smtp:Enabled") ?? false;
var smtpHost = builder.Configuration["Smtp:Host"];
var useRealSmtp = smtpEnabled && !string.IsNullOrWhiteSpace(smtpHost) && smtpHost != "CHANGE_ME";

// Printed unconditionally (not behind ILogger, which isn't built yet) so a wrong Smtp:Enabled/
// Smtp:Host reading is visible immediately at startup instead of silently falling back to the
// dummy sender -- appsettings.json path resolution issues (stale copy in bin\, wrong working
// directory, etc.) show up here as the values not matching what's actually in the file.
Console.WriteLine($"[Startup] Smtp:Enabled={smtpEnabled}, Smtp:Host=\"{smtpHost}\" -> {(useRealSmtp ? "SmtpEmailNotificationService (real mail will be sent)" : "DummyEmailNotificationService (log only, no mail sent)")}");
Console.WriteLine($"[Startup] appsettings.json read from: {Path.Combine(AppContext.BaseDirectory, "appsettings.json")}");

if (useRealSmtp)
{
    builder.Services.AddScoped<IEmailNotificationService, SmtpEmailNotificationService>();
}
else
{
    builder.Services.AddScoped<IEmailNotificationService, DummyEmailNotificationService>();
}

var upcomingWindowDays = builder.Configuration.GetValue<int?>("ExpirationNotifier:UpcomingWindowDays") ?? 90;
builder.Services.AddScoped(sp => new ExpirationCheckService(
    sp.GetRequiredService<ITInventoryDbContext>(),
    sp.GetRequiredService<IEmailNotificationService>(),
    sp.GetRequiredService<ILogger<ExpirationCheckService>>(),
    upcomingWindowDays));

builder.Services.AddHostedService<ExpirationCheckWorker>();

// A Windows Service has no console to watch -- write a plain daily text log too, next to
// whatever's built-in (console when run interactively, Windows Event Log when installed
// as a service, both wired up automatically by AddWindowsService above).
var logDirectory = Path.Combine(AppContext.BaseDirectory, "logs");
builder.Logging.AddProvider(new FileLoggerProvider(logDirectory));

var host = builder.Build();
await host.RunAsync();
'@
Write-RepoFile -RelativePath 'src\ITInventory.ExpirationNotifier\Program.cs' -Content $f_Program_cs

$f_DummyEmailNotificationService_cs = @'
using ITInventory.ExpirationNotifier.Models;
using Microsoft.Extensions.Logging;

namespace ITInventory.ExpirationNotifier.Services;

/// <summary>
/// Placeholder until the real mail service is wired in. Logs what would be sent to whom so
/// the call site (ExpirationCheckService) and its data shape are already final; swap the
/// registration in Program.cs for a real implementation later without touching anything else.
/// </summary>
public class DummyEmailNotificationService : IEmailNotificationService
{
    private readonly ILogger<DummyEmailNotificationService> _logger;

    public DummyEmailNotificationService(ILogger<DummyEmailNotificationService> logger)
    {
        _logger = logger;
    }

    public Task NotifyAsync(IReadOnlyList<CountryNotificationGroup> groups)
    {
        foreach (var group in groups)
        {
            if (group.Recipients.Count == 0)
            {
                _logger.LogWarning("[DUMMY EMAIL] {Country}: {ExpiredCount} expired, {UpcomingCount} upcoming, but no recipient email is configured (no matching YDUsers.Email and no admin has one either).",
                    group.CountryName, group.ExpiredItems.Count, group.UpcomingItems.Count);
                continue;
            }

            var recipientList = string.Join(", ", group.Recipients.Select(r => $"{r.FullName} <{r.Email}>"));
            _logger.LogInformation("[DUMMY EMAIL] {Country} -> {Recipients}: {ExpiredCount} expired, {UpcomingCount} upcoming.",
                group.CountryName, recipientList, group.ExpiredItems.Count, group.UpcomingItems.Count);

            foreach (var item in group.ExpiredItems)
                _logger.LogInformation("[DUMMY EMAIL]   EXPIRED  - {Label} '{Name}' - {ExpirationType} - {ExpiresAt:dd.MM.yyyy}",
                    item.Label, item.Name, item.ExpirationType, item.ExpiresAt);

            foreach (var item in group.UpcomingItems)
                _logger.LogInformation("[DUMMY EMAIL]   UPCOMING - {Label} '{Name}' - {ExpirationType} - {ExpiresAt:dd.MM.yyyy}",
                    item.Label, item.Name, item.ExpirationType, item.ExpiresAt);
        }

        return Task.CompletedTask;
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.ExpirationNotifier\Services\DummyEmailNotificationService.cs' -Content $f_DummyEmailNotificationService_cs

