$f_AccountController_cs = @'
using System.Security.Claims;
using ITInventory.Data;
using ITInventory.Web.Configuration;
using ITInventory.Web.Models.Account;
using ITInventory.Web.Services;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace ITInventory.Web.Controllers;

[RequireHttps]
public class AccountController : Controller
{
    private readonly ILdapAuthenticationService _ldapAuth;
    private readonly ITInventoryDbContext _db;
    private readonly ILogger<AccountController> _logger;
    private readonly IActivityLogger _activityLogger;

    public AccountController(
        ILdapAuthenticationService ldapAuth,
        ITInventoryDbContext db,
        ILogger<AccountController> logger,
        IActivityLogger activityLogger)
    {
        _ldapAuth = ldapAuth;
        _db = db;
        _logger = logger;
        _activityLogger = activityLogger;
    }

    [HttpGet]
    [AllowAnonymous]
    public IActionResult Login(string? returnUrl = null)
    {
        return View(new LoginViewModel { ReturnUrl = returnUrl });
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    [AllowAnonymous]
    public async Task<IActionResult> Login(LoginViewModel model)
    {
        if (!ModelState.IsValid)
            return View(model);

        // AD/LDAP is the only way in. The old "test user" mode is gone entirely: it carried a
        // second credential store and a PBKDF2 verifier whose salt was read back out of the
        // stored string, and none of it earned its keep once LDAP was working.
        if (!_ldapAuth.ValidateCredentials(model.Username, model.Password, out var ldapError))
        {
            ModelState.AddModelError(string.Empty, ldapError ?? "Invalid username or password.");
            return View(model);
        }

        var bareUsername = model.Username.Contains('@') ? model.Username.Split('@')[0] : model.Username;

        var user = await _db.YdUsers
            .Include(u => u.UserRoles)
            .ThenInclude(ur => ur.Role)
            .FirstOrDefaultAsync(u => u.Username == bareUsername);

        if (user is null || !user.IsActive)
        {
            _logger.LogWarning(
                "Authentication succeeded but the user is not registered/active in the IT Inventory system: {Username}",
                bareUsername);
            ModelState.AddModelError(string.Empty,
                "This user is not registered in the IT Inventory system. Please contact your system administrator.");
            return View(model);
        }

        var roles = user.UserRoles
            .Select(ur => ur.Role?.RoleName)
            .Where(r => !string.IsNullOrEmpty(r))
            .Cast<string>()
            .ToList();

        if (roles.Count == 0)
        {
            ModelState.AddModelError(string.Empty,
                "No role is assigned to this user. Please contact your system administrator.");
            return View(model);
        }

        var claims = new List<Claim>
        {
            new(ClaimTypes.NameIdentifier, user.Id.ToString()),
            new(ClaimTypes.Name, user.Username),
            new(AppClaimTypes.FullName, user.FullName),
        };

        if (!string.IsNullOrWhiteSpace(user.RepositoryName))
        {
            claims.Add(new Claim(AppClaimTypes.Country, user.RepositoryName));

            var country = await _db.Countries.FirstOrDefaultAsync(c => c.Name == user.RepositoryName);
            if (country is not null)
            {
                claims.Add(new Claim(AppClaimTypes.CountryId, country.Id.ToString()));
                if (!string.IsNullOrWhiteSpace(country.DisplayName))
                    claims.Add(new Claim(AppClaimTypes.CountryDisplayName, country.DisplayName));
            }
        }

        claims.AddRange(roles.Select(r => new Claim(ClaimTypes.Role, r)));

        var identity = new ClaimsIdentity(claims, CookieAuthenticationDefaults.AuthenticationScheme);
        var principal = new ClaimsPrincipal(identity);

        await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme, principal, new AuthenticationProperties
        {
            IsPersistent = false,
            ExpiresUtc = DateTimeOffset.UtcNow.AddHours(8)
        });

        // SignInAsync only sets the auth cookie for future requests -- HttpContext.User still
        // reflects the anonymous principal from the start of this request unless set here, so
        // without this the login's own ActivityLog row would be written with an empty username.
        HttpContext.User = principal;
        await _activityLogger.LogAsync("Login", "User", user.Username);

        if (!string.IsNullOrEmpty(model.ReturnUrl) && Url.IsLocalUrl(model.ReturnUrl))
            return LocalRedirect(model.ReturnUrl);

        return RedirectToAction("Index", "Home");
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    [Authorize]
    public async Task<IActionResult> Logout()
    {
        var username = User.FindFirstValue(ClaimTypes.Name);
        if (!string.IsNullOrEmpty(username))
            await _activityLogger.LogAsync("Logout", "User", username);
        await HttpContext.SignOutAsync(CookieAuthenticationDefaults.AuthenticationScheme);
        return RedirectToAction(nameof(Login));
    }

    [AllowAnonymous]
    [HttpGet]
    public IActionResult AccessDenied()
    {
        return View();
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Controllers\AccountController.cs' -Content $f_AccountController_cs

$f_AdminActivityLogController_cs = @'
using ITInventory.Data;
using ITInventory.Data.Common;
using ITInventory.Data.Entities;
using ITInventory.Web.Models;
using ITInventory.Web.Services;
using ITInventory.Web.Services.Import;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ITInventory.Web.Controllers;

[Authorize(Roles = RoleNames.Admin)]
public class AdminActivityLogController : Controller
{
    private static readonly string[] Actions = { "Create", "Update", "Delete", "Import", "Export", "Login", "Logout" };

    private static readonly string[] EntityTypes =
    {
        "PhysicalDevice", "Server", "ServerEndpoint", "License", "Circuit", "Company", "Application",
        "User", "Country", "OriginCountry", "Location", "DeviceProfile", "ActivityLog"
    };

    private readonly ITInventoryDbContext _db;
    private readonly IActivityLogger _activityLogger;

    public AdminActivityLogController(ITInventoryDbContext db, IActivityLogger activityLogger)
    {
        _db = db;
        _activityLogger = activityLogger;
    }

    // Renamed from "action" to "actionFilter": "action" is a reserved MVC routing token (which
    // controller action method to invoke), so a parameter literally named "action" gets bound
    // from route data ("Index", the current action's own name) instead of the query string --
    // the filter dropdown's real value was silently discarded and replaced with "Index", which
    // never matches any ActivityLogs.Action value, so the filtered result was always empty.
    [HttpGet]
    public async Task<IActionResult> Index(string? username, string? actionFilter, string? entityType, DateTime? fromDate, DateTime? toDate, int page = 1)
    {
        // Only the first filter/search submit (the hidden "searched" field) triggers a query --
        // a bare navigation to the page (no querystring at all) shows the filter form and
        // nothing else, so a genuinely empty log table can never be mistaken for "the page is
        // broken" and a real result set is never confused with "you forgot to search".
        var hasSearched = Request.Query.ContainsKey("searched");

        ViewBag.HasSearched = hasSearched;
        ViewBag.ActionOptions = Actions;
        ViewBag.EntityTypeOptions = EntityTypes;
        ViewBag.Username = username;
        ViewBag.SelectedAction = actionFilter;
        ViewBag.SelectedEntityType = entityType;
        ViewBag.FromDate = fromDate?.ToString("yyyy-MM-dd");
        ViewBag.ToDate = toDate?.ToString("yyyy-MM-dd");

        if (!hasSearched)
        {
            return View(new PagedResult<ActivityLog> { Items = Array.Empty<ActivityLog>(), PageNumber = 1, PageSize = PaginationExtensions.DefaultPageSize, TotalCount = 0 });
        }

        var query = BuildFilteredQuery(username, actionFilter, entityType, fromDate, toDate);
        var items = await query.OrderByDescending(l => l.CreatedAt).ToPagedResultAsync(page);

        return View(items);
    }

    [HttpGet]
    public async Task<IActionResult> Export(string? username, string? actionFilter, string? entityType, DateTime? fromDate, DateTime? toDate)
    {
        var query = BuildFilteredQuery(username, actionFilter, entityType, fromDate, toDate);
        var items = await query.OrderByDescending(l => l.CreatedAt).ToListAsync();

        var headers = new[] { "Time", "Username", "Full Name", "Country", "Action", "Entity Type", "Entity Name", "Details", "Environment" };
        var rows = items.Select(l => new object?[]
        {
            l.CreatedAt,
            l.Username,
            l.FullName,
            l.CountryName,
            l.Action,
            l.EntityType,
            l.EntityName,
            l.Details,
            l.EnvironmentName
        });

        var bytes = ExcelImportHelpers.CreateExportBytes("Activity Log", headers, rows);
        await _activityLogger.LogAsync("Export", "ActivityLog", details: $"{items.Count} record(s) exported to Excel.");
        return File(bytes, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", $"ActivityLog_Export_{DateTime.UtcNow:yyyyMMdd_HHmmss}.xlsx");
    }

    private IQueryable<ActivityLog> BuildFilteredQuery(string? username, string? actionFilter, string? entityType, DateTime? fromDate, DateTime? toDate)
    {
        var query = _db.ActivityLogs.AsQueryable();

        if (!string.IsNullOrWhiteSpace(username))
            query = query.Where(l => l.Username.Contains(username) || (l.FullName != null && l.FullName.Contains(username)));

        if (!string.IsNullOrWhiteSpace(actionFilter))
            query = query.Where(l => l.Action == actionFilter);

        if (!string.IsNullOrWhiteSpace(entityType))
            query = query.Where(l => l.EntityType == entityType);

        // CreatedAt is stored as UTC (DateTime.UtcNow), but fromDate/toDate are calendar days
        // picked in the admin's local time (same convention the table already uses to *display*
        // CreatedAt via ToLocalTime()). Comparing a UTC column directly against a naive local
        // date boundary is off by the server's UTC offset, so the local day boundaries are
        // converted to UTC first.
        if (fromDate.HasValue)
        {
            var fromUtc = TimeZoneInfo.ConvertTimeToUtc(DateTime.SpecifyKind(fromDate.Value.Date, DateTimeKind.Unspecified), TimeZoneInfo.Local);
            query = query.Where(l => l.CreatedAt >= fromUtc);
        }

        if (toDate.HasValue)
        {
            var toUtcExclusive = TimeZoneInfo.ConvertTimeToUtc(DateTime.SpecifyKind(toDate.Value.Date.AddDays(1), DateTimeKind.Unspecified), TimeZoneInfo.Local);
            query = query.Where(l => l.CreatedAt < toUtcExclusive);
        }

        return query;
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Controllers\AdminActivityLogController.cs' -Content $f_AdminActivityLogController_cs

$f_AdminCountriesController_cs = @'
using ITInventory.Data;
using ITInventory.Data.Common;
using ITInventory.Data.Entities;
using ITInventory.Web.Common;
using ITInventory.Web.Models.Admin;
using ITInventory.Web.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ITInventory.Web.Controllers;

[Authorize(Roles = RoleNames.Admin)]
public class AdminCountriesController : Controller
{
    private readonly ITInventoryDbContext _db;
    private readonly IActivityLogger _activityLogger;
    private readonly ICurrentUserService _currentUser;

    public AdminCountriesController(ITInventoryDbContext db, IActivityLogger activityLogger, ICurrentUserService currentUser)
    {
        _db = db;
        _activityLogger = activityLogger;
        _currentUser = currentUser;
    }

    [HttpGet]
    public async Task<IActionResult> Index()
    {
        var countries = await _db.Countries.OrderBy(c => c.Name).ToListAsync();
        return View(countries);
    }

    [HttpGet]
    public IActionResult Create() => View(new CountryFormViewModel());

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Create(CountryFormViewModel vm)
    {
        if (await _db.Countries.AnyAsync(c => c.Name == vm.Name))
            ModelState.AddModelError(nameof(vm.Name), "A country with this name already exists.");

        if (!ModelState.IsValid)
            return View(vm);

        _db.Countries.Add(new Country
        {
            Name = vm.Name,
            DisplayName = vm.DisplayName,
            Code = vm.Code,
            IsActive = vm.IsActive,
            CreatedAt = DateTime.UtcNow
        });

        await _db.SaveChangesAsync();
        await _activityLogger.LogAsync("Create", "Country", vm.DisplayName ?? vm.Name);
        return RedirectToAction(nameof(Index));
    }

    [HttpGet]
    public async Task<IActionResult> Edit(int id)
    {
        var isAdmin = User.IsAdministrator();

        var country = await _db.Countries.FirstOrDefaultAsync(c => c.Id == id && isAdmin);
        if (country is null) return NotFound();

        return View(new CountryFormViewModel
        {
            Id = country.Id,
            Name = country.Name,
            DisplayName = country.DisplayName,
            Code = country.Code,
            IsActive = country.IsActive
        });
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Edit(int id, CountryFormViewModel vm)
    {
        var isAdmin = User.IsAdministrator();

        if (id != vm.Id) return BadRequest();

        if (await _db.Countries.AnyAsync(c => c.Name == vm.Name && c.Id != id))
            ModelState.AddModelError(nameof(vm.Name), "A country with this name already exists.");

        if (!ModelState.IsValid)
            return View(vm);

        var country = await _db.Countries.FirstOrDefaultAsync(c => c.Id == id && isAdmin);
        if (country is null) return NotFound();

        country.Name = vm.Name;
        country.DisplayName = vm.DisplayName;
        country.Code = vm.Code;
        country.IsActive = vm.IsActive;
        country.UpdatedAt = DateTime.UtcNow;

        await _db.SaveChangesAsync();
        await _activityLogger.LogAsync("Update", "Country", country.DisplayName ?? country.Name);
        return RedirectToAction(nameof(Index));
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Delete(int id)
    {
        var isAdmin = User.IsAdministrator();

        var country = await _db.Countries.FirstOrDefaultAsync(c => c.Id == id && isAdmin);
        if (country is null) return NotFound();

        var countryLabel = country.DisplayName ?? country.Name;

        // Seven different tables carry a CountryId FK (Restrict) into Countries -- Physical
        // Devices/Servers/Licenses/Circuits are the obvious "inventory" ones, but Companies,
        // Applications, and Locations (branches) also reference it and are easy to forget to
        // check, so a generic "records are linked" message left the admin guessing which one.
        // Naming the exact table(s) here instead turns that into a one-look answer.
        var blockers = new List<string>();
        if (await _db.PhysicalDevices.AnyAsync(x => x.CountryId == id)) blockers.Add("Physical Devices");
        if (await _db.Servers.AnyAsync(x => x.CountryId == id)) blockers.Add("Servers");
        if (await _db.Licenses.AnyAsync(x => x.CountryId == id)) blockers.Add("Licenses");
        if (await _db.Circuits.AnyAsync(x => x.CountryId == id)) blockers.Add("Circuits");
        if (await _db.Companies.AnyAsync(x => x.CountryId == id)) blockers.Add("Companies");
        if (await _db.Applications.AnyAsync(x => x.CountryId == id)) blockers.Add("Applications");
        if (await _db.Locations.AnyAsync(x => x.CountryId == id)) blockers.Add("Locations (Branches)");

        if (blockers.Count > 0)
        {
            TempData["Error"] = $"Could not delete '{countryLabel}' because it still has records in: {string.Join(", ", blockers)}. Delete or move those first.";
            return RedirectToAction(nameof(Index));
        }

        _db.Countries.Remove(country);

        try
        {
            await _db.SaveChangesAsync();
            await _activityLogger.LogAsync("Delete", "Country", countryLabel);
        }
        catch (DbUpdateException)
        {
            TempData["Error"] = $"Could not delete '{countryLabel}' because inventory records are linked to it. Delete or move the related records first.";
        }

        return RedirectToAction(nameof(Index));
    }
}
