$f_AdminOriginCountriesController_cs = @'
using ITInventory.Data;
using ITInventory.Data.Common;
using ITInventory.Data.Entities;
using ITInventory.Web.Common;
using ITInventory.Web.Models.Admin;
using ITInventory.Web.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ITInventory.Web.Controllers;

[Authorize(Roles = RoleNames.Admin)]
public class AdminOriginCountriesController : Controller
{
    private readonly ITInventoryDbContext _db;
    private readonly IActivityLogger _activityLogger;
    private readonly ICurrentUserService _currentUser;

    public AdminOriginCountriesController(ITInventoryDbContext db, IActivityLogger activityLogger, ICurrentUserService currentUser)
    {
        _db = db;
        _activityLogger = activityLogger;
        _currentUser = currentUser;
    }

    [HttpGet]
    public async Task<IActionResult> Index()
    {
        var originCountries = await _db.OriginCountries.OrderBy(c => c.Name).ToListAsync();
        return View(originCountries);
    }

    [HttpGet]
    public IActionResult Create() => View(new OriginCountryFormViewModel());

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Create(OriginCountryFormViewModel vm)
    {
        if (await _db.OriginCountries.AnyAsync(c => c.Name == vm.Name))
            ModelState.AddModelError(nameof(vm.Name), "A country with this name already exists.");

        if (!ModelState.IsValid)
            return View(vm);

        _db.OriginCountries.Add(new OriginCountry
        {
            Name = vm.Name,
            IsActive = vm.IsActive,
            CreatedAt = DateTime.UtcNow
        });

        await _db.SaveChangesAsync();
        await _activityLogger.LogAsync("Create", "OriginCountry", vm.Name);
        return RedirectToAction(nameof(Index));
    }

    [HttpGet]
    public async Task<IActionResult> Edit(int id)
    {
        var isAdmin = User.IsAdministrator();

        var originCountry = await _db.OriginCountries.FirstOrDefaultAsync(o => o.Id == id && isAdmin);
        if (originCountry is null) return NotFound();

        return View(new OriginCountryFormViewModel
        {
            Id = originCountry.Id,
            Name = originCountry.Name,
            IsActive = originCountry.IsActive
        });
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Edit(int id, OriginCountryFormViewModel vm)
    {
        var isAdmin = User.IsAdministrator();

        if (id != vm.Id) return BadRequest();

        if (await _db.OriginCountries.AnyAsync(c => c.Name == vm.Name && c.Id != id))
            ModelState.AddModelError(nameof(vm.Name), "A country with this name already exists.");

        if (!ModelState.IsValid)
            return View(vm);

        var originCountry = await _db.OriginCountries.FirstOrDefaultAsync(o => o.Id == id && isAdmin);
        if (originCountry is null) return NotFound();

        originCountry.Name = vm.Name;
        originCountry.IsActive = vm.IsActive;
        originCountry.UpdatedAt = DateTime.UtcNow;

        await _db.SaveChangesAsync();
        await _activityLogger.LogAsync("Update", "OriginCountry", originCountry.Name);
        return RedirectToAction(nameof(Index));
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Delete(int id)
    {
        var isAdmin = User.IsAdministrator();

        var originCountry = await _db.OriginCountries.FirstOrDefaultAsync(o => o.Id == id && isAdmin);
        if (originCountry is null) return NotFound();

        var name = originCountry.Name;
        _db.OriginCountries.Remove(originCountry);

        try
        {
            await _db.SaveChangesAsync();
            await _activityLogger.LogAsync("Delete", "OriginCountry", name);
        }
        catch (DbUpdateException)
        {
            TempData["Error"] = "Could not delete because companies are linked to this country. Unlink them first.";
        }

        return RedirectToAction(nameof(Index));
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Controllers\AdminOriginCountriesController.cs' -Content $f_AdminOriginCountriesController_cs

$f_AdminUsersController_cs = @'
using ITInventory.Data;
using ITInventory.Data.Common;
using ITInventory.Data.Entities;
using ITInventory.Web.Common;
using ITInventory.Web.Models.Admin;
using ITInventory.Web.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;

namespace ITInventory.Web.Controllers;

[Authorize(Roles = RoleNames.Admin)]
public class AdminUsersController : Controller
{
    private readonly ITInventoryDbContext _db;
    private readonly IActivityLogger _activityLogger;
    private readonly ICurrentUserService _currentUser;

    public AdminUsersController(ITInventoryDbContext db, IActivityLogger activityLogger, ICurrentUserService currentUser)
    {
        _db = db;
        _activityLogger = activityLogger;
        _currentUser = currentUser;
    }

    [HttpGet]
    public async Task<IActionResult> Index()
    {
        var users = await _db.YdUsers
            .Include(u => u.UserRoles)
            .ThenInclude(ur => ur.Role)
            .OrderBy(u => u.Username)
            .ToListAsync();

        ViewBag.CountryDisplayNames = await _db.Countries
            .Where(c => c.DisplayName != null)
            .ToDictionaryAsync(c => c.Name, c => c.DisplayName!);

        return View(users);
    }

    [HttpGet]
    public async Task<IActionResult> Create()
    {
        await PopulateDropdowns();
        return View(new UserFormViewModel());
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Create(UserFormViewModel vm, List<int>? selectedRoleIds)
    {
        var isAdmin = User.IsAdministrator();

        var requestedRoleIds = selectedRoleIds ?? new List<int>();

        if (await _db.YdUsers.AnyAsync(u => u.Username == vm.Username))
            ModelState.AddModelError(nameof(vm.Username), "This username already exists.");

        var validRoleIds = await _db.YdRoles.Select(r => r.Id).ToListAsync();
        if (requestedRoleIds.Except(validRoleIds).Any())
            ModelState.AddModelError(string.Empty, "One or more selected roles are invalid.");

        if (!ModelState.IsValid)
        {
            await PopulateDropdowns(requestedRoleIds);
            return View(vm);
        }

        var country = vm.CountryId.HasValue ? await _db.Countries.FirstOrDefaultAsync(c => c.Id == vm.CountryId.Value && isAdmin) : null;

        var user = new YdUser
        {
            Username = vm.Username,
            FullName = vm.FullName,
            Email = vm.Email,
            RepositoryName = country?.Name,
            IsActive = vm.IsActive,
            ReceiveExpirationNotifications = vm.ReceiveExpirationNotifications,
            CreatedAt = DateTime.UtcNow
        };

        foreach (var roleId in requestedRoleIds)
            user.UserRoles.Add(new YdUserRole { RoleId = roleId });

        _db.YdUsers.Add(user);
        await _db.SaveChangesAsync();
        await _activityLogger.LogAsync("Create", "User", user.Username);
        return RedirectToAction(nameof(Index));
    }

    [HttpGet]
    public async Task<IActionResult> Edit(int id)
    {
        var isAdmin = User.IsAdministrator();

        var user = await _db.YdUsers
            .Include(u => u.UserRoles)
            .FirstOrDefaultAsync(u => u.Id == id && isAdmin);
        if (user is null) return NotFound();

        var country = !string.IsNullOrEmpty(user.RepositoryName)
            ? await _db.Countries.FirstOrDefaultAsync(c => c.Name == user.RepositoryName)
            : null;

        var vm = new UserFormViewModel
        {
            Id = user.Id,
            Username = user.Username,
            FullName = user.FullName,
            Email = user.Email,
            CountryId = country?.Id,
            IsActive = user.IsActive,
            ReceiveExpirationNotifications = user.ReceiveExpirationNotifications
        };

        await PopulateDropdowns(user.UserRoles.Select(ur => ur.RoleId));
        return View(vm);
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Edit(int id, UserFormViewModel vm, List<int>? selectedRoleIds)
    {
        var isAdmin = User.IsAdministrator();

        if (id != vm.Id) return BadRequest();

        var requestedRoleIds = selectedRoleIds ?? new List<int>();

        if (await _db.YdUsers.AnyAsync(u => u.Username == vm.Username && u.Id != id))
            ModelState.AddModelError(nameof(vm.Username), "This username already exists.");

        var validRoleIds = await _db.YdRoles.Select(r => r.Id).ToListAsync();
        if (requestedRoleIds.Except(validRoleIds).Any())
            ModelState.AddModelError(string.Empty, "One or more selected roles are invalid.");

        if (!ModelState.IsValid)
        {
            await PopulateDropdowns(requestedRoleIds);
            return View(vm);
        }

        var user = await _db.YdUsers
            .Include(u => u.UserRoles)
            .FirstOrDefaultAsync(u => u.Id == id && isAdmin);
        if (user is null) return NotFound();

        var country = vm.CountryId.HasValue ? await _db.Countries.FirstOrDefaultAsync(c => c.Id == vm.CountryId.Value && isAdmin) : null;

        user.Username = vm.Username;
        user.FullName = vm.FullName;
        user.Email = vm.Email;
        user.RepositoryName = country?.Name;
        user.IsActive = vm.IsActive;
        user.ReceiveExpirationNotifications = vm.ReceiveExpirationNotifications;

        user.UserRoles.Clear();
        foreach (var roleId in requestedRoleIds)
            user.UserRoles.Add(new YdUserRole { UserId = user.Id, RoleId = roleId });

        await _db.SaveChangesAsync();
        await _activityLogger.LogAsync("Update", "User", user.Username);
        return RedirectToAction(nameof(Index));
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Delete(int id)
    {
        var isAdmin = User.IsAdministrator();

        var user = await _db.YdUsers.FirstOrDefaultAsync(u => u.Id == id && isAdmin);
        if (user is null) return NotFound();

        var username = user.Username;
        _db.YdUsers.Remove(user);
        await _db.SaveChangesAsync();
        await _activityLogger.LogAsync("Delete", "User", username);
        return RedirectToAction(nameof(Index));
    }

    private async Task PopulateDropdowns(IEnumerable<int>? selectedRoleIds = null)
    {
        ViewBag.SelectedRoleIds = (selectedRoleIds ?? Enumerable.Empty<int>()).ToHashSet();
        var countries = await _db.Countries.OrderBy(c => c.Name).Select(c => new { c.Id, Label = c.DisplayName ?? c.Name }).ToListAsync();
        ViewBag.CountryOptions = new SelectList(countries, "Id", "Label");
        ViewBag.Roles = await _db.YdRoles.OrderBy(r => r.RoleName).ToListAsync();
    }
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Controllers\AdminUsersController.cs' -Content $f_AdminUsersController_cs

$f_ApplicationsController_cs = @'
using ClosedXML.Excel;
using ITInventory.Data;
using ITInventory.Data.Common;
using ITInventory.Data.Entities;
using ITInventory.Web.Common;
using ITInventory.Web.Models;
using ITInventory.Web.Models.Applications;
using ITInventory.Web.Models.Import;
using ITInventory.Web.Services;
using ITInventory.Web.Services.Import;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;

namespace ITInventory.Web.Controllers;

public class ApplicationsController : Controller
{
    private readonly ITInventoryDbContext _db;
    private readonly ICurrentUserService _currentUser;
    private readonly IActivityLogger _activityLogger;

    public ApplicationsController(ITInventoryDbContext db, ICurrentUserService currentUser, IActivityLogger activityLogger)
    {
        _db = db;
        _currentUser = currentUser;
        _activityLogger = activityLogger;
    }

    [HttpGet]
    public async Task<IActionResult> Index(string? countryId, int page = 1)
    {
        var isAdmin = User.IsAdministrator();
        var scopedCountryId = User.ScopedCountryId();

        var viewAll = isAdmin && countryId == "all";
        int? selectedCountryId = !viewAll && int.TryParse(countryId, out var parsedCountryId) ? parsedCountryId : null;
        var requiresSelection = isAdmin && !viewAll && !selectedCountryId.HasValue;

        PagedResult<Application> items;
        if (requiresSelection)
        {
            items = new PagedResult<Application> { Items = Array.Empty<Application>(), PageNumber = 1, PageSize = PaginationExtensions.DefaultPageSize, TotalCount = 0 };
        }
        else
        {
            var query = _db.Applications
                .Include(a => a.Country)
                .Include(a => a.Company)
                .Include(a => a.License)
                .AsQueryable();

            if (!isAdmin)
                query = query.Where(a => a.CountryId == scopedCountryId);
            else if (selectedCountryId.HasValue)
                query = query.Where(a => a.CountryId == selectedCountryId.Value);

            items = await query.OrderBy(a => a.Country!.Name).ThenBy(a => a.Name).ToPagedResultAsync(page);
        }

        ViewBag.Countries = await _db.Countries.OrderBy(c => c.Name).ToListAsync();
        ViewBag.SelectedCountryId = selectedCountryId;
        ViewBag.ViewAll = viewAll;
        ViewBag.RequiresSelection = requiresSelection;
        ViewBag.CanEdit = _currentUser.CanEdit;
        ViewBag.IsAdmin = isAdmin;

        return View(items);
    }

    [HttpGet]
    public async Task<IActionResult> Export(string? countryId)
    {
        var isAdmin = User.IsAdministrator();

        if (!isAdmin) return Forbid();

        var viewAll = countryId == "all";
        int? selectedCountryId = !viewAll && int.TryParse(countryId, out var parsedCountryId) ? parsedCountryId : null;
        if (!viewAll && !selectedCountryId.HasValue) return BadRequest("Please select a country (or All Countries) first.");

        var query = _db.Applications.Include(a => a.Country).Include(a => a.Company).Include(a => a.License).AsQueryable();
        if (selectedCountryId.HasValue)
            query = query.Where(a => a.CountryId == selectedCountryId.Value);

        var items = await query.OrderBy(a => a.Country!.Name).ThenBy(a => a.Name).ToListAsync();

        var headers = new[]
        {
            "Country", "Application Name", "Company", "License", "Application Type",
            "Externally Exposed?", "URL", "Cloud Application?", "Notes"
        };
        var rows = items.Select(a => new object?[]
        {
            a.Country?.DisplayName ?? a.Country?.Name,
            a.Name,
            a.Company?.Name,
            a.License?.LicenseName,
            a.ApplicationType.ToString(),
            a.IsExternallyExposed ? "Yes" : "No",
            a.Url,
            a.IsCloudApplication ? "Yes" : "No",
            a.Notes
        });

        var bytes = ExcelImportHelpers.CreateExportBytes("Applications", headers, rows);
        await _activityLogger.LogAsync("Export", "Application", details: $"{items.Count} record(s) exported to Excel.");
        return File(bytes, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", $"Applications_Export_{DateTime.UtcNow:yyyyMMdd_HHmmss}.xlsx");
    }

    [HttpGet]
    public async Task<IActionResult> Create()
    {
        var isAdmin = User.IsAdministrator();
        var scopedCountryId = User.ScopedCountryId();

        if (!_currentUser.CanEdit) return Forbid();

        var vm = new ApplicationFormViewModel
        {
            CountryId = isAdmin ? 0 : scopedCountryId ?? 0
        };

        await PopulateDropdowns();
        return View(vm);
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Create(ApplicationFormViewModel vm)
    {
        var isAdmin = User.IsAdministrator();
        var scopedCountryId = User.ScopedCountryId();

        if (!_currentUser.CanEdit) return Forbid();

        if (!isAdmin)
            vm.CountryId = scopedCountryId ?? 0;

        // Every foreign key below arrives as a plain number from a form field. Checking that the
        // number exists is not enough: the ids written into the new row have to COME FROM the
        // rows the authorized lookups returned, never from the request. Otherwise the posted
        // values still travel straight into the INSERT with only an existence test in the way.
        var country = await _db.Countries.FirstOrDefaultAsync(c => c.Id == (vm.CountryId ?? 0)
            && (isAdmin || c.Id == scopedCountryId));
        if (country is null)
        {
            ModelState.AddModelError(nameof(vm.CountryId), "Please select a valid country.");
            await PopulateDropdowns();
            return View(vm);
        }

        Company? company = null;
        if (vm.CompanyId.HasValue)
        {
            company = await _db.Companies.FirstOrDefaultAsync(c => c.Id == vm.CompanyId.Value && c.IsActive
                && (isAdmin || c.CountryId == scopedCountryId));
            if (company is null)
            {
                ModelState.AddModelError(nameof(vm.CompanyId), "Please select a valid company.");
                await PopulateDropdowns();
                return View(vm);
            }
        }

        License? license = null;
        if (vm.LicenseId.HasValue)
        {
            license = await _db.Licenses.FirstOrDefaultAsync(l => l.Id == vm.LicenseId.Value
                && (isAdmin || l.CountryId == scopedCountryId));
            if (license is null)
            {
                ModelState.AddModelError(nameof(vm.LicenseId), "Please select a valid license.");
                await PopulateDropdowns();
                return View(vm);
            }
        }

        if (!ModelState.IsValid)
        {
            await PopulateDropdowns();
            return View(vm);
        }

        var entity = new Application
        {
            CountryId = country.Id,
            Name = vm.Name,
            CompanyId = company?.Id,
            LicenseId = license?.Id,
            ApplicationType = vm.ApplicationType!.Value,
            IsExternallyExposed = vm.IsExternallyExposed,
            Url = vm.Url,
            IsCloudApplication = vm.IsCloudApplication,
            Notes = vm.Notes,
            CreatedAt = DateTime.UtcNow,
            CreatedBy = _currentUser.Username
        };

        _db.Applications.Add(entity);
        await _db.SaveChangesAsync();
        await _activityLogger.LogAsync("Create", "Application", entity.Name);
        return RedirectToAction(nameof(Index));
    }

    [HttpGet]
    public async Task<IActionResult> Edit(int id)
    {
        var isAdmin = User.IsAdministrator();
        var scopedCountryId = User.ScopedCountryId();

        if (!_currentUser.CanEdit) return Forbid();

        var entity = await _db.Applications.FirstOrDefaultAsync(x => x.Id == id && (isAdmin || x.CountryId == scopedCountryId));
        if (entity is null) return NotFound();

        var vm = new ApplicationFormViewModel
        {
            Id = entity.Id,
            CountryId = entity.CountryId,
            Name = entity.Name,
            CompanyId = entity.CompanyId,
            LicenseId = entity.LicenseId,
            ApplicationType = entity.ApplicationType,
            IsExternallyExposed = entity.IsExternallyExposed,
            Url = entity.Url,
            IsCloudApplication = entity.IsCloudApplication,
            Notes = entity.Notes
        };

        await PopulateDropdowns();
        return View(vm);
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Edit(int id, ApplicationFormViewModel vm)
    {
        var isAdmin = User.IsAdministrator();
        var scopedCountryId = User.ScopedCountryId();

        if (!_currentUser.CanEdit) return Forbid();
        if (id != vm.Id) return BadRequest();

        var entity = await _db.Applications.FirstOrDefaultAsync(x => x.Id == id && (isAdmin || x.CountryId == scopedCountryId));
        if (entity is null) return NotFound();

        if (!isAdmin)
            vm.CountryId = scopedCountryId ?? 0;

        // Every foreign key below arrives as a plain number from a form field. Checking that the
        // number exists is not enough: the ids written onto the row have to COME FROM the rows
        // the authorized lookups returned, never from the request. Otherwise the posted values
        // still travel straight into the UPDATE with only an existence test in the way.
        var country = await _db.Countries.FirstOrDefaultAsync(c => c.Id == (vm.CountryId ?? 0)
            && (isAdmin || c.Id == scopedCountryId));
        if (country is null)
        {
            ModelState.AddModelError(nameof(vm.CountryId), "Please select a valid country.");
            await PopulateDropdowns();
            return View(vm);
        }

        Company? company = null;
        if (vm.CompanyId.HasValue)
        {
            company = await _db.Companies.FirstOrDefaultAsync(c => c.Id == vm.CompanyId.Value && c.IsActive
                && (isAdmin || c.CountryId == scopedCountryId));
            if (company is null)
            {
                ModelState.AddModelError(nameof(vm.CompanyId), "Please select a valid company.");
                await PopulateDropdowns();
                return View(vm);
            }
        }

        License? license = null;
        if (vm.LicenseId.HasValue)
        {
            license = await _db.Licenses.FirstOrDefaultAsync(l => l.Id == vm.LicenseId.Value
                && (isAdmin || l.CountryId == scopedCountryId));
            if (license is null)
            {
                ModelState.AddModelError(nameof(vm.LicenseId), "Please select a valid license.");
                await PopulateDropdowns();
                return View(vm);
            }
        }

        if (!ModelState.IsValid)
        {
            await PopulateDropdowns();
            return View(vm);
        }

        entity.CountryId = country.Id;
        entity.Name = vm.Name;
        entity.CompanyId = company?.Id;
        entity.LicenseId = license?.Id;
        entity.ApplicationType = vm.ApplicationType!.Value;
        entity.IsExternallyExposed = vm.IsExternallyExposed;
        entity.Url = vm.Url;
        entity.IsCloudApplication = vm.IsCloudApplication;
        entity.Notes = vm.Notes;
        entity.UpdatedAt = DateTime.UtcNow;
        entity.UpdatedBy = _currentUser.Username;

        await _db.SaveChangesAsync();
        await _activityLogger.LogAsync("Update", "Application", entity.Name);
        return RedirectToAction(nameof(Index));
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Delete(int id)
    {
        var isAdmin = User.IsAdministrator();
        var scopedCountryId = User.ScopedCountryId();

        if (!_currentUser.CanEdit) return Forbid();

        var entity = await _db.Applications.FirstOrDefaultAsync(x => x.Id == id && (isAdmin || x.CountryId == scopedCountryId));
        if (entity is null) return NotFound();

        var appName = entity.Name;
        _db.Applications.Remove(entity);

        try
        {
            await _db.SaveChangesAsync();
            await _activityLogger.LogAsync("Delete", "Application", appName);
        }
        catch (DbUpdateException)
        {
            TempData["ImportError"] = "Could not delete because servers are linked to this application. Unlink them first.";
        }

        return RedirectToAction(nameof(Index));
    }

    [HttpGet]
    public async Task<IActionResult> Import()
