$f_Index_cshtml_2 = @'
@model List<ITInventory.Data.Entities.Country>
@{
    ViewData["Title"] = "Countries";
}

<div class="flex items-center justify-between mb-6">
    <h2 class="text-xl font-semibold text-slate-900">Countries</h2>
    <a asp-action="Create" class="inline-flex items-center gap-2 bg-brand-600 hover:bg-brand-700 text-white text-sm font-medium px-4 py-2 rounded-md">
        <i class="fa-solid fa-plus"></i>New Country
    </a>
</div>

@if (TempData["Error"] is string error)
{
    <div class="bg-red-50 border border-red-200 text-red-700 rounded-md px-4 py-3 text-sm mb-4">@error</div>
}

<div class="mb-4 relative max-w-xs">
    <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>
    <input type="text" oninput="filterRows(this, 'countries-table')" placeholder="Search countries..."
           class="w-full pl-9 pr-3 py-2 text-sm rounded-md border border-slate-300 focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
</div>

<div class="bg-white rounded-lg shadow-sm border border-slate-200 overflow-x-auto">
    <table id="countries-table" class="min-w-full divide-y divide-slate-200 text-sm">
        <thead class="bg-slate-50">
            <tr>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Display Name</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Repository Name (Nessus)</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Code</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Active</th>
                <th class="px-4 py-3"></th>
            </tr>
        </thead>
        <tbody class="divide-y divide-slate-100">
            @foreach (var c in Model)
            {
                <tr class="hover:bg-slate-50">
                    <td class="px-4 py-3 text-slate-700 font-medium">@(c.DisplayName ?? c.Name)</td>
                    <td class="px-4 py-3 text-slate-500 font-mono text-xs">@c.Name</td>
                    <td class="px-4 py-3 text-slate-700">@c.Code</td>
                    <td class="px-4 py-3">
                        @if (c.IsActive)
                        {
                            <span class="inline-flex items-center gap-1 text-brand-700 bg-brand-50 px-2 py-0.5 rounded-full text-xs font-medium"><i class="fa-solid fa-circle-check"></i>Yes</span>
                        }
                        else
                        {
                            <span class="inline-flex items-center gap-1 text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full text-xs font-medium">No</span>
                        }
                    </td>
                    <td class="px-4 py-3 text-right whitespace-nowrap">
                        <a asp-action="Edit" asp-route-id="@c.Id" class="text-brand-600 hover:text-brand-800 mr-3" title="Edit"><i class="fa-solid fa-pen"></i></a>
                        <button type="button" onclick="openConfirmModal('delete-form-@c.Id', 'Are you sure you want to delete this country?')" class="text-red-600 hover:text-red-800" title="Delete"><i class="fa-solid fa-trash"></i></button>
                        <form id="delete-form-@c.Id" asp-action="Delete" asp-route-id="@c.Id" method="post" class="hidden"></form>
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\AdminCountries\Index.cshtml' -Content $f_Index_cshtml_2

$f__Form_cshtml = @'
@model ITInventory.Web.Models.Admin.CountryFormViewModel

<div asp-validation-summary="ModelOnly" class="text-sm text-red-600 mb-3"></div>
<input type="hidden" asp-for="Id" />

<div class="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
    <div>
        <label asp-for="Name" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <input asp-for="Name" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        <span asp-validation-for="Name" class="text-sm text-red-600"></span>
        <p class="text-xs text-slate-400 mt-1">
            Must exactly match the value in the Nessus scan data (Ziraat_YD.RepositoryName),
            otherwise the device pool will not work for this country.
        </p>
    </div>
    <div>
        <label asp-for="DisplayName" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <input asp-for="DisplayName" placeholder="e.g. ZiraatBank AG" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        <p class="text-xs text-slate-400 mt-1">Shown everywhere in the app instead of the raw name above. Leave blank to show the raw name.</p>
    </div>
    <div>
        <label asp-for="Code" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <input asp-for="Code" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
    </div>
</div>

<div class="flex items-center gap-2 mb-6">
    <input asp-for="IsActive" class="rounded border-slate-300 text-brand-600 focus:ring-brand-500" />
    <label asp-for="IsActive" class="text-sm font-medium text-slate-700"></label>
</div>

<div class="flex gap-2">
    <button type="submit" class="bg-brand-600 hover:bg-brand-700 text-white text-sm font-medium px-5 py-2.5 rounded-md">Save</button>
    <a asp-action="Index" class="border border-slate-300 text-slate-700 hover:bg-slate-50 text-sm font-medium px-5 py-2.5 rounded-md">Cancel</a>
</div>
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\AdminCountries\_Form.cshtml' -Content $f__Form_cshtml

$f_Index_cshtml_3 = @'
@model List<ITInventory.Data.Entities.DeviceProfileCatalog>
@{
    ViewData["Title"] = "Device Profiles";
    var categories = (List<ITInventory.Data.Entities.DeviceCategory>)ViewBag.Categories;
}

<h2 class="text-xl font-semibold text-slate-900 mb-1">Device Profiles (Nessus DeviceProfile Mapping)</h2>
<p class="text-sm text-slate-500 mb-6">
    Assign each DeviceProfile value seen in Nessus scans to an inventory category here.
    The device pool uses this mapping.
</p>

<div class="mb-4 relative max-w-xs">
    <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>
    <input type="text" oninput="filterRows(this, 'profiles-table')" placeholder="Search profiles..."
           class="w-full pl-9 pr-3 py-2 text-sm rounded-md border border-slate-300 focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
</div>

<div class="bg-white rounded-lg shadow-sm border border-slate-200 overflow-x-auto">
    <table id="profiles-table" class="min-w-full divide-y divide-slate-200 text-sm">
        <thead class="bg-slate-50">
            <tr>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Device Profile (Nessus)</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Category</th>
            </tr>
        </thead>
        <tbody class="divide-y divide-slate-100">
            @foreach (var p in Model)
            {
                <tr class="hover:bg-slate-50">
                    <td class="px-4 py-3">
                        <div class="text-slate-700 font-medium">@(p.DisplayName ?? p.ProfileName)</div>
                        @if (!string.IsNullOrEmpty(p.DisplayName) && p.DisplayName != p.ProfileName)
                        {
                            <div class="text-xs text-slate-400 font-mono">@p.ProfileName</div>
                        }
                    </td>
                    <td class="px-4 py-3">
                        <form asp-action="UpdateCategory" asp-route-id="@p.Id" method="post" class="flex items-center gap-2">
                            <select name="categoryId" class="rounded-md border border-slate-300 px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
                                <option value="">-- No Category --</option>
                                @foreach (var cat in categories)
                                {
                                    <option value="@cat.Id" selected="@(cat.Id == p.CategoryId)">@cat.Name</option>
                                }
                            </select>
                            <button type="submit" class="text-brand-600 hover:text-brand-800 text-sm font-medium px-2 py-1"><i class="fa-solid fa-check mr-1"></i>Save</button>
                        </form>
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\AdminDeviceProfiles\Index.cshtml' -Content $f_Index_cshtml_3

