$f_Index_cshtml_6 = @'
@model List<ITInventory.Data.Entities.YdUser>
@{
    ViewData["Title"] = "Users";
    var countryDisplayNames = (Dictionary<string, string>)ViewBag.CountryDisplayNames;
}

<div class="flex items-center justify-between mb-6">
    <h2 class="text-xl font-semibold text-slate-900">Users</h2>
    <a asp-action="Create" class="inline-flex items-center gap-2 bg-brand-600 hover:bg-brand-700 text-white text-sm font-medium px-4 py-2 rounded-md">
        <i class="fa-solid fa-plus"></i>New User
    </a>
</div>

<div class="mb-4 relative max-w-xs">
    <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>
    <input type="text" oninput="filterRows(this, 'users-table')" placeholder="Search users..."
           class="w-full pl-9 pr-3 py-2 text-sm rounded-md border border-slate-300 focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
</div>

<div class="bg-white rounded-lg shadow-sm border border-slate-200 overflow-x-auto">
    <table id="users-table" class="min-w-full divide-y divide-slate-200 text-sm">
        <thead class="bg-slate-50">
            <tr>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Username</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Full Name</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Email</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Country/Branch</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Roles</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Active</th>
                <th class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Notifications</th>
                <th class="px-4 py-3"></th>
            </tr>
        </thead>
        <tbody class="divide-y divide-slate-100">
            @foreach (var user in Model)
            {
                <tr class="hover:bg-slate-50">
                    <td class="px-4 py-3 text-slate-700 font-medium">@user.Username</td>
                    <td class="px-4 py-3 text-slate-700">@user.FullName</td>
                    <td class="px-4 py-3 text-slate-700">@user.Email</td>
                    <td class="px-4 py-3 text-slate-700">
                    @(user.RepositoryName != null && countryDisplayNames.TryGetValue(user.RepositoryName, out var cdn) ? cdn : user.RepositoryName)
                </td>
                    <td class="px-4 py-3">
                        @foreach (var r in user.UserRoles)
                        {
                            <span class="inline-block bg-slate-100 text-slate-600 text-xs px-2 py-0.5 rounded-full mr-1 mb-1">@r.Role?.RoleName</span>
                        }
                    </td>
                    <td class="px-4 py-3">
                        @if (user.IsActive)
                        {
                            <span class="inline-flex items-center gap-1 text-brand-700 bg-brand-50 px-2 py-0.5 rounded-full text-xs font-medium"><i class="fa-solid fa-circle-check"></i>Yes</span>
                        }
                        else
                        {
                            <span class="inline-flex items-center gap-1 text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full text-xs font-medium">No</span>
                        }
                    </td>
                    <td class="px-4 py-3">
                        @if (user.ReceiveExpirationNotifications)
                        {
                            <span class="inline-flex items-center gap-1 text-brand-700 bg-brand-50 px-2 py-0.5 rounded-full text-xs font-medium"><i class="fa-solid fa-envelope"></i>Yes</span>
                        }
                        else
                        {
                            <span class="inline-flex items-center gap-1 text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full text-xs font-medium">No</span>
                        }
                    </td>
                    <td class="px-4 py-3 text-right whitespace-nowrap">
                        <a asp-action="Edit" asp-route-id="@user.Id" class="text-brand-600 hover:text-brand-800 mr-3" title="Edit"><i class="fa-solid fa-pen"></i></a>
                        <button type="button" onclick="openConfirmModal('delete-form-@user.Id', 'Are you sure you want to delete this user?')" class="text-red-600 hover:text-red-800" title="Delete"><i class="fa-solid fa-trash"></i></button>
                        <form id="delete-form-@user.Id" asp-action="Delete" asp-route-id="@user.Id" method="post" class="hidden"></form>
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\AdminUsers\Index.cshtml' -Content $f_Index_cshtml_6

$f__Form_cshtml_4 = @'
@model ITInventory.Web.Models.Admin.UserFormViewModel
@{
    var countryOptions = (Microsoft.AspNetCore.Mvc.Rendering.SelectList)ViewBag.CountryOptions;
    var roles = (List<ITInventory.Data.Entities.YdRole>)ViewBag.Roles;
    // Role membership isn't part of the bound model on purpose (see UserFormViewModel) -- the
    // checkboxes post to the action's own selectedRoleIds parameter, and the current selection
    // comes from the controller rather than from the model.
    var selectedRoleIds = (HashSet<int>)ViewBag.SelectedRoleIds;
}

<div asp-validation-summary="ModelOnly" class="text-sm text-red-600 mb-3"></div>
<input type="hidden" asp-for="Id" />

<div class="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
    <div>
        <label asp-for="Username" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <input asp-for="Username" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        <span asp-validation-for="Username" class="text-sm text-red-600"></span>
        <p class="text-xs text-slate-400 mt-1">AD username (without the fintek.local\ prefix).</p>
    </div>
    <div>
        <label asp-for="FullName" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <input asp-for="FullName" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        <span asp-validation-for="FullName" class="text-sm text-red-600"></span>
    </div>
    <div>
        <label asp-for="Email" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <input asp-for="Email" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        <span asp-validation-for="Email" class="text-sm text-red-600"></span>
    </div>
</div>

<div class="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4 items-end">
    <div>
        <label asp-for="CountryId" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <select asp-for="CountryId" asp-items="countryOptions" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
            <option value="">-- Not selected (e.g. admin) --</option>
        </select>
    </div>
    <div class="flex items-center gap-2 pb-2">
        <input asp-for="IsActive" class="rounded border-slate-300 text-brand-600 focus:ring-brand-500" />
        <label asp-for="IsActive" class="text-sm font-medium text-slate-700"></label>
    </div>
    <div class="flex items-center gap-2 pb-2">
        <input asp-for="ReceiveExpirationNotifications" class="rounded border-slate-300 text-brand-600 focus:ring-brand-500" />
        <label asp-for="ReceiveExpirationNotifications" class="text-sm font-medium text-slate-700"></label>
    </div>
</div>

<div class="mb-6">
    <label class="block text-sm font-medium text-slate-700 mb-2">Roles</label>
    <div class="flex flex-wrap gap-3">
        @foreach (var role in roles)
        {
            <label class="inline-flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-md px-3 py-1.5 text-sm cursor-pointer hover:bg-slate-100">
                <input type="checkbox" class="rounded border-slate-300 text-brand-600 focus:ring-brand-500" name="selectedRoleIds" value="@role.Id"
                       checked="@selectedRoleIds.Contains(role.Id)" />
                @role.RoleName
            </label>
        }
    </div>
</div>

<div class="flex gap-2">
    <button type="submit" class="bg-brand-600 hover:bg-brand-700 text-white text-sm font-medium px-5 py-2.5 rounded-md">Save</button>
    <a asp-action="Index" class="border border-slate-300 text-slate-700 hover:bg-slate-50 text-sm font-medium px-5 py-2.5 rounded-md">Cancel</a>
</div>
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\AdminUsers\_Form.cshtml' -Content $f__Form_cshtml_4

