$f_Index_cshtml_7 = @'
@model ITInventory.Web.Models.PagedResult<ITInventory.Data.Entities.Application>
@{
    ViewData["Title"] = "Applications";
    var countries = (List<ITInventory.Data.Entities.Country>)ViewBag.Countries;
    int? selectedCountryId = ViewBag.SelectedCountryId;
    bool canEdit = ViewBag.CanEdit;
    bool isAdmin = ViewBag.IsAdmin;
    bool viewAll = ViewBag.ViewAll;
    bool requiresSelection = ViewBag.RequiresSelection;
    string? exportCountryId = viewAll ? "all" : selectedCountryId?.ToString();
}

<div class="flex items-center justify-between mb-6">
    <h2 class="text-xl font-semibold text-slate-900">Applications</h2>
    <div class="flex gap-2">
        @if (isAdmin && !requiresSelection)
        {
            <a asp-action="Export" asp-route-countryId="@exportCountryId" class="inline-flex items-center gap-2 border border-slate-300 text-slate-700 hover:bg-slate-50 text-sm font-medium px-4 py-2 rounded-md">
                <i class="fa-solid fa-file-arrow-down"></i>Export to Excel
            </a>
        }
        @if (isAdmin)
        {
            <a asp-action="Import" class="inline-flex items-center gap-2 border border-slate-300 text-slate-700 hover:bg-slate-50 text-sm font-medium px-4 py-2 rounded-md">
                <i class="fa-solid fa-file-excel"></i>Import from Excel
            </a>
        }
        @if (canEdit)
        {
            <a asp-action="Create" class="inline-flex items-center gap-2 bg-brand-600 hover:bg-brand-700 text-white text-sm font-medium px-4 py-2 rounded-md">
                <i class="fa-solid fa-plus"></i>Add New Application
            </a>
        }
    </div>
</div>

<div class="flex flex-wrap items-center gap-3 mb-4">
    @if (isAdmin)
    {
        <form method="get">
            <select name="countryId" onchange="showLoadingOverlay(); this.form.submit();" class="rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
                <option value="" selected="@(requiresSelection)">-- Select Country --</option>
                <option value="all" selected="@viewAll">All Countries</option>
                @foreach (var c in countries)
                {
                    <option value="@c.Id" selected="@(c.Id == selectedCountryId)">@(c.DisplayName ?? c.Name)</option>
                }
            </select>
        </form>
    }
    <div class="flex items-center gap-2 ml-auto">
        <div class="relative max-w-xs">
            <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>
            <input type="text" oninput="filterRows(this, 'applications-table')" placeholder="Search applications..."
                   class="w-full pl-9 pr-3 py-2 text-sm rounded-md border border-slate-300 focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        </div>
        @await Html.PartialAsync("_ColumnChooserButton", "applications-table")
    </div>
</div>

@if (requiresSelection)
{
    <div class="bg-blue-50 border border-blue-200 text-blue-700 rounded-md px-4 py-3 text-sm">
        <i class="fa-solid fa-circle-info mr-1.5"></i>Select a country above (or choose "All Countries") to view records.
    </div>
}
else if (!Model.Items.Any())
{
    <div class="text-center py-12 text-slate-400 bg-white rounded-lg border border-slate-200">
        <i class="fa-solid fa-inbox text-3xl mb-2"></i>
        <p class="text-sm">No records found.</p>
    </div>
}
else
{
    <div class="bg-white rounded-lg shadow-sm border border-slate-200">
    <div class="overflow-x-auto">
        <table id="applications-table" data-colchooser="colprefs:applications" class="min-w-full divide-y divide-slate-200 text-sm">
            <thead class="bg-slate-50">
                <tr>
                    @if (isAdmin)
                    {
                        <th data-col="country" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Country</th>
                    }
                    <th data-col="name" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Application Name</th>
                    <th data-col="company" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Company</th>
                    <th data-col="license" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">License</th>
                    <th data-col="type" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Type</th>
                    <th data-col="external" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Externally Exposed?</th>
                    <th data-col="cloud" data-default-hidden="true" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Cloud?</th>
                    <th data-col="url" data-default-hidden="true" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">URL</th>
                    <th data-col="notes" data-default-hidden="true" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Notes</th>
                    @if (canEdit)
                    {
                        <th class="px-4 py-3"></th>
                    }
                </tr>
            </thead>
            <tbody class="divide-y divide-slate-100">
                @foreach (var item in Model.Items)
                {
                    <tr class="hover:bg-slate-50">
                        @if (isAdmin)
                        {
                            <td data-col="country" class="px-4 py-3 text-slate-700">@(item.Country?.DisplayName ?? item.Country?.Name)</td>
                        }
                        <td data-col="name" class="px-4 py-3 text-slate-700 font-medium">@item.Name</td>
                        <td data-col="company" class="px-4 py-3 text-slate-700">@item.Company?.Name</td>
                        <td data-col="license" class="px-4 py-3 text-slate-700">@item.License?.LicenseName</td>
                        <td data-col="type" class="px-4 py-3 text-slate-700">@item.ApplicationType</td>
                        <td data-col="external" class="px-4 py-3">
                            @if (item.IsExternallyExposed)
                            {
                                <span class="inline-flex items-center gap-1 text-amber-700 bg-amber-50 px-2 py-0.5 rounded-full text-xs font-medium">Yes</span>
                            }
                            else
                            {
                                <span class="inline-flex items-center gap-1 text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full text-xs font-medium">No</span>
                            }
                        </td>
                        <td data-col="cloud" class="px-4 py-3 text-slate-700">@(item.IsCloudApplication ? "Yes" : "No")</td>
                        <td data-col="url" class="px-4 py-3 text-slate-700">
                            @if (!string.IsNullOrEmpty(item.Url))
                            {
                                <a href="@item.Url" target="_blank" rel="noopener" class="text-brand-600 hover:underline">@item.Url</a>
                            }
                        </td>
                        <td data-col="notes" class="px-4 py-3 text-slate-700 max-w-xs truncate" title="@item.Notes">@item.Notes</td>
                        @if (canEdit)
                        {
                            <td class="px-4 py-3 text-right whitespace-nowrap">
                                <a asp-action="Edit" asp-route-id="@item.Id" class="text-brand-600 hover:text-brand-800 mr-3" title="Edit"><i class="fa-solid fa-pen"></i></a>
                                <button type="button" onclick="openConfirmModal('delete-form-@item.Id', 'Are you sure you want to delete this record?')" class="text-red-600 hover:text-red-800" title="Delete"><i class="fa-solid fa-trash"></i></button>
                                <form id="delete-form-@item.Id" asp-action="Delete" asp-route-id="@item.Id" method="post" class="hidden"></form>
                            </td>
                        }
                    </tr>
                }
            </tbody>
        </table>
    </div>
    @await Html.PartialAsync("_Pagination", ITInventory.Web.Models.PaginationInfo.From(Model))
    </div>
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\Applications\Index.cshtml' -Content $f_Index_cshtml_7

$f__Form_cshtml_5 = @'
@model ITInventory.Web.Models.Applications.ApplicationFormViewModel
@{
    var countryOptions = (Microsoft.AspNetCore.Mvc.Rendering.SelectList)ViewBag.CountryOptions;
    var companyOptions = (Microsoft.AspNetCore.Mvc.Rendering.SelectList)ViewBag.CompanyOptions;
    var licenseOptions = (Microsoft.AspNetCore.Mvc.Rendering.SelectList)ViewBag.LicenseOptions;
    bool isAdmin = ViewBag.IsAdmin ?? false;
}

<div asp-validation-summary="ModelOnly" class="text-sm text-red-600 mb-3"></div>
<input type="hidden" asp-for="Id" />

<div class="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
    <div>
        <label asp-for="CountryId" class="block text-sm font-medium text-slate-700 mb-1"></label>
        @if (isAdmin)
        {
            <select asp-for="CountryId" asp-items="countryOptions" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
                <option value="">-- Select --</option>
            </select>
        }
        else
        {
            <select asp-for="CountryId" asp-items="countryOptions" class="w-full rounded-md border border-slate-200 bg-slate-100 px-3 py-2 text-sm" disabled></select>
            <input type="hidden" asp-for="CountryId" />
        }
        <span asp-validation-for="CountryId" class="text-sm text-red-600"></span>
    </div>
    <div>
        <label asp-for="Name" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <input asp-for="Name" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        <span asp-validation-for="Name" class="text-sm text-red-600"></span>
    </div>
    <div>
        <label asp-for="ApplicationType" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <select asp-for="ApplicationType" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
            <option value="">-- Select --</option>
            <option value="Mobile">Mobile</option>
            <option value="Web">Web</option>
            <option value="Desktop">Desktop</option>
        </select>
        <span asp-validation-for="ApplicationType" class="text-sm text-red-600"></span>
    </div>
</div>

<div class="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
    <div>
        <label asp-for="CompanyId" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <select asp-for="CompanyId" asp-items="companyOptions" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
            <option value="">-- Select --</option>
        </select>
        <span asp-validation-for="CompanyId" class="text-sm text-red-600"></span>
    </div>
    <div>
        <label asp-for="LicenseId" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <select asp-for="LicenseId" asp-items="licenseOptions" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
            <option value="">-- Select --</option>
        </select>
        <span asp-validation-for="LicenseId" class="text-sm text-red-600"></span>
    </div>
</div>

<div class="mb-4">
    <label asp-for="Url" class="block text-sm font-medium text-slate-700 mb-1"></label>
    <input asp-for="Url" placeholder="https://..." class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
    <span asp-validation-for="Url" class="text-sm text-red-600"></span>
</div>

<div class="flex flex-wrap items-center gap-6 mb-6">
    <div class="flex items-center gap-2">
        <input asp-for="IsExternallyExposed" class="rounded border-slate-300 text-brand-600 focus:ring-brand-500" />
        <label asp-for="IsExternallyExposed" class="text-sm font-medium text-slate-700"></label>
    </div>
    <div class="flex items-center gap-2">
        <input asp-for="IsCloudApplication" class="rounded border-slate-300 text-brand-600 focus:ring-brand-500" />
        <label asp-for="IsCloudApplication" class="text-sm font-medium text-slate-700"></label>
    </div>
</div>

<div class="mb-6">
    <label asp-for="Notes" class="block text-sm font-medium text-slate-700 mb-1"></label>
    <textarea asp-for="Notes" rows="3" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500"></textarea>
</div>

<div class="flex gap-2">
    <button type="submit" class="bg-brand-600 hover:bg-brand-700 text-white text-sm font-medium px-5 py-2.5 rounded-md">Save</button>
    <a asp-action="Index" class="border border-slate-300 text-slate-700 hover:bg-slate-50 text-sm font-medium px-5 py-2.5 rounded-md">Cancel</a>
</div>
'@
