$f_Create_cshtml_10 = @'
@model ITInventory.Web.Models.ServerEndpoints.ServerEndpointFormViewModel
@{
    ViewData["Title"] = "New Server Endpoint";
}

<h2 class="text-xl font-semibold text-slate-900 mb-6">New Server Endpoint</h2>

<div class="bg-white rounded-lg shadow-sm border border-slate-200 p-6 max-w-3xl">
    <form asp-action="Create" method="post">
        @await Html.PartialAsync("_Form", Model)
    </form>
</div>
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\ServerEndpoints\Create.cshtml' -Content $f_Create_cshtml_10

$f_Edit_cshtml_10 = @'
@model ITInventory.Web.Models.ServerEndpoints.ServerEndpointFormViewModel
@{
    ViewData["Title"] = "Edit Server Endpoint";
}

<h2 class="text-xl font-semibold text-slate-900 mb-6">Edit Server Endpoint</h2>

<div class="bg-white rounded-lg shadow-sm border border-slate-200 p-6 max-w-3xl">
    <form asp-action="Edit" asp-route-id="@Model.Id" method="post">
        @await Html.PartialAsync("_Form", Model)
    </form>
</div>
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\ServerEndpoints\Edit.cshtml' -Content $f_Edit_cshtml_10

$f_Index_cshtml_15 = @'
@model ITInventory.Web.Models.PagedResult<ITInventory.Data.Entities.ServerEndpoint>
@{
    ViewData["Title"] = "Server Endpoints";
    var countries = (List<ITInventory.Data.Entities.Country>)ViewBag.Countries;
    int? selectedCountryId = ViewBag.SelectedCountryId;
    bool canEdit = ViewBag.CanEdit;
    bool isAdmin = ViewBag.IsAdmin;
    bool viewAll = ViewBag.ViewAll;
    bool requiresSelection = ViewBag.RequiresSelection;
    string? exportCountryId = viewAll ? "all" : selectedCountryId?.ToString();
}

<div class="flex items-center justify-between mb-6">
    <h2 class="text-xl font-semibold text-slate-900">Server Endpoints</h2>
    <div class="flex gap-2">
        @if (isAdmin && !requiresSelection)
        {
            <a asp-action="Export" asp-route-countryId="@exportCountryId" class="inline-flex items-center gap-2 border border-slate-300 text-slate-700 hover:bg-slate-50 text-sm font-medium px-4 py-2 rounded-md">
                <i class="fa-solid fa-file-arrow-down"></i>Export to Excel
            </a>
        }
        @if (canEdit)
        {
            <a asp-action="Create" class="inline-flex items-center gap-2 bg-brand-600 hover:bg-brand-700 text-white text-sm font-medium px-4 py-2 rounded-md">
                <i class="fa-solid fa-plus"></i>Add New Endpoint
            </a>
        }
    </div>
</div>

<p class="text-sm text-slate-500 mb-4">
    IP:PORT to Application mappings. Each row links one endpoint on a server (from the Servers page)
    to the application it hosts. A server can have multiple endpoints here.
</p>

<div class="flex flex-wrap items-center gap-3 mb-4">
    @if (isAdmin)
    {
        <form method="get">
            <select name="countryId" onchange="showLoadingOverlay(); this.form.submit();" class="rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
                <option value="" selected="@(requiresSelection)">-- Select Country --</option>
                <option value="all" selected="@viewAll">All Countries</option>
                @foreach (var c in countries)
                {
                    <option value="@c.Id" selected="@(c.Id == selectedCountryId)">@(c.DisplayName ?? c.Name)</option>
                }
            </select>
        </form>
    }
    <div class="flex items-center gap-2 ml-auto">
        <div class="relative max-w-xs">
            <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>
            <input type="text" oninput="filterRows(this, 'server-endpoints-table')" placeholder="Search endpoints..."
                   class="w-full pl-9 pr-3 py-2 text-sm rounded-md border border-slate-300 focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        </div>
        @await Html.PartialAsync("_ColumnChooserButton", "server-endpoints-table")
    </div>
</div>

@if (requiresSelection)
{
    <div class="bg-blue-50 border border-blue-200 text-blue-700 rounded-md px-4 py-3 text-sm">
        <i class="fa-solid fa-circle-info mr-1.5"></i>Select a country above (or choose "All Countries") to view records.
    </div>
}
else if (!Model.Items.Any())
{
    <div class="text-center py-12 text-slate-400 bg-white rounded-lg border border-slate-200">
        <i class="fa-solid fa-inbox text-3xl mb-2"></i>
        <p class="text-sm">No records found.</p>
    </div>
}
else
{
    <div class="bg-white rounded-lg shadow-sm border border-slate-200">
    <div class="overflow-x-auto">
        <table id="server-endpoints-table" data-colchooser="colprefs:serverendpoints" class="min-w-full divide-y divide-slate-200 text-sm">
            <thead class="bg-slate-50">
                <tr>
                    @if (isAdmin)
                    {
                        <th data-col="country" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Country</th>
                    }
                    <th data-col="server" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Server</th>
                    <th data-col="ip" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">IP Address</th>
                    <th data-col="port" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Port</th>
                    <th data-col="application" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Application</th>
                    <th data-col="notes" data-default-hidden="true" class="px-4 py-3 text-left font-medium text-slate-500 uppercase tracking-wider text-xs">Notes</th>
                    @if (canEdit)
                    {
                        <th class="px-4 py-3"></th>
                    }
                </tr>
            </thead>
            <tbody class="divide-y divide-slate-100">
                @foreach (var item in Model.Items)
                {
                    <tr class="hover:bg-slate-50">
                        @if (isAdmin)
                        {
                            <td data-col="country" class="px-4 py-3 text-slate-700">@(item.Server?.Country?.DisplayName ?? item.Server?.Country?.Name)</td>
                        }
                        <td data-col="server" class="px-4 py-3 text-slate-700 font-medium">@item.Server?.HostName</td>
                        <td data-col="ip" class="px-4 py-3 text-slate-700 font-mono text-xs">@item.IpAddress</td>
                        <td data-col="port" class="px-4 py-3 text-slate-700">@item.Port</td>
                        <td data-col="application" class="px-4 py-3 text-slate-700">@item.Application?.Name</td>
                        <td data-col="notes" class="px-4 py-3 text-slate-700 max-w-xs truncate" title="@item.Notes">@item.Notes</td>
                        @if (canEdit)
                        {
                            <td class="px-4 py-3 text-right whitespace-nowrap">
                                <a asp-action="Edit" asp-route-id="@item.Id" class="text-brand-600 hover:text-brand-800 mr-3" title="Edit"><i class="fa-solid fa-pen"></i></a>
                                <button type="button" onclick="openConfirmModal('delete-form-@item.Id', 'Are you sure you want to delete this record?')" class="text-red-600 hover:text-red-800" title="Delete"><i class="fa-solid fa-trash"></i></button>
                                <form id="delete-form-@item.Id" asp-action="Delete" asp-route-id="@item.Id" method="post" class="hidden"></form>
                            </td>
                        }
                    </tr>
                }
            </tbody>
        </table>
    </div>
    @await Html.PartialAsync("_Pagination", ITInventory.Web.Models.PaginationInfo.From(Model))
    </div>
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\ServerEndpoints\Index.cshtml' -Content $f_Index_cshtml_15

$f__Form_cshtml_10 = @'
@model ITInventory.Web.Models.ServerEndpoints.ServerEndpointFormViewModel
@{
    var serverOptions = (Microsoft.AspNetCore.Mvc.Rendering.SelectList)ViewBag.ServerOptions;
    var applicationOptions = (Microsoft.AspNetCore.Mvc.Rendering.SelectList)ViewBag.ApplicationOptions;
}

<div asp-validation-summary="ModelOnly" class="text-sm text-red-600 mb-3"></div>
<input type="hidden" asp-for="Id" />

<div class="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
    <div>
        <label asp-for="ServerId" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <select asp-for="ServerId" asp-items="serverOptions" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
            <option value="">-- Select --</option>
        </select>
        <span asp-validation-for="ServerId" class="text-sm text-red-600"></span>
    </div>
    <div>
        <label asp-for="ApplicationId" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <select asp-for="ApplicationId" asp-items="applicationOptions" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500">
            <option value="">-- Select --</option>
        </select>
        <span asp-validation-for="ApplicationId" class="text-sm text-red-600"></span>
    </div>
</div>

<div class="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
    <div>
        <label asp-for="IpAddress" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <input asp-for="IpAddress" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        <span asp-validation-for="IpAddress" class="text-sm text-red-600"></span>
    </div>
    <div>
        <label asp-for="Port" class="block text-sm font-medium text-slate-700 mb-1"></label>
        <input asp-for="Port" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500" />
        <span asp-validation-for="Port" class="text-sm text-red-600"></span>
    </div>
</div>

<div class="mb-6">
    <label asp-for="Notes" class="block text-sm font-medium text-slate-700 mb-1"></label>
    <textarea asp-for="Notes" rows="3" class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500"></textarea>
</div>

<div class="flex gap-2">
    <button type="submit" class="bg-brand-600 hover:bg-brand-700 text-white text-sm font-medium px-5 py-2.5 rounded-md">Save</button>
    <a asp-action="Index" class="border border-slate-300 text-slate-700 hover:bg-slate-50 text-sm font-medium px-5 py-2.5 rounded-md">Cancel</a>
</div>
