$f__Layout_cshtml_css = @'
/* Styling is now handled by Tailwind utility classes directly in the views. */
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\Shared\_Layout.cshtml.css' -Content $f__Layout_cshtml_css

$f__LoginLayout_cshtml = @'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>@ViewData["Title"] - IT Inventory</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <script>
        tailwind.config = {
            theme: {
                extend: {
                    colors: {
                        brand: {
                            50: '#ecfdf5', 100: '#d1fae5', 500: '#10b981',
                            600: '#059669', 700: '#047857'
                        }
                    }
                }
            }
        }
    </script>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" />
    <link rel="stylesheet" href="~/css/site.css" asp-append-version="true" />
</head>
<body class="min-h-screen bg-slate-100 flex items-center justify-center p-4">
    @RenderBody()
    <script src="~/js/site.js" asp-append-version="true"></script>
    @await RenderSectionAsync("Scripts", required: false)
</body>
</html>
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\Shared\_LoginLayout.cshtml' -Content $f__LoginLayout_cshtml

$f__Pagination_cshtml = @'
@model ITInventory.Web.Models.PaginationInfo
@{
    var baseParams = Context.Request.Query
        .Where(q => !string.Equals(q.Key, "page", StringComparison.OrdinalIgnoreCase))
        .SelectMany(q => q.Value.Select(v => $"{Uri.EscapeDataString(q.Key)}={Uri.EscapeDataString(v ?? string.Empty)}"))
        .ToList();

    string PageUrl(int page)
    {
        var parts = new List<string>(baseParams) { $"page={page}" };
        return "?" + string.Join("&", parts);
    }

    var from = Model.TotalCount == 0 ? 0 : (Model.PageNumber - 1) * Model.PageSize + 1;
    var to = Math.Min(Model.PageNumber * Model.PageSize, Model.TotalCount);
}
@if (Model.TotalCount > 0)
{
    <div class="flex items-center justify-between px-4 py-3 border-t border-slate-200 text-sm text-slate-600">
        <span>Showing @from&ndash;@to of @Model.TotalCount</span>
        @if (Model.TotalPages > 1)
        {
            <div class="flex items-center gap-1">
                @if (Model.HasPrevious)
                {
                    <a href="@PageUrl(Model.PageNumber - 1)" onclick="showLoadingOverlay()" class="px-3 py-1.5 rounded-md border border-slate-300 hover:bg-slate-50 text-slate-700">
                        <i class="fa-solid fa-chevron-left"></i>
                    </a>
                }
                else
                {
                    <span class="px-3 py-1.5 rounded-md border border-slate-200 text-slate-300"><i class="fa-solid fa-chevron-left"></i></span>
                }
                <span class="px-3 py-1.5 text-slate-700">Page @Model.PageNumber / @Model.TotalPages</span>
                @if (Model.HasNext)
                {
                    <a href="@PageUrl(Model.PageNumber + 1)" onclick="showLoadingOverlay()" class="px-3 py-1.5 rounded-md border border-slate-300 hover:bg-slate-50 text-slate-700">
                        <i class="fa-solid fa-chevron-right"></i>
                    </a>
                }
                else
                {
                    <span class="px-3 py-1.5 rounded-md border border-slate-200 text-slate-300"><i class="fa-solid fa-chevron-right"></i></span>
                }
            </div>
        }
    </div>
}
'@
Write-RepoFile -RelativePath 'src\ITInventory.Web\Views\Shared\_Pagination.cshtml' -Content $f__Pagination_cshtml

